void startAnimationFor(Unit unit) {
    String name = unit.getName();
    FBFAnimation fBFAnimation = animations().get(unit.getName());
    if (fBFAnimation == null) {
        return;
    }
    if ((fBFAnimation.hasNoRange() || fBFAnimation.toIndices(this.mCartoonStage.scene())[0] == unit.getOwnFrame().mOriginFrameIndex) ? true : this.mAnimationStates.containsKey(name)) {
        AnimationState animationState = this.mAnimationStates.get(name);
        if (animationState == null) {
            animationState = new AnimationState();
        }
        if ((animationState.counter + 1) % fBFAnimation.period == 0) {
            Pair<Integer, Boolean> pairNextState = unit.nextState(this.mCartoonStage.mUnitsAssets, new Pair<>(Integer.valueOf(animationState.assetsState), Boolean.valueOf(animationState.direction)), fBFAnimation.loop);
            animationState.assetsState = ((Integer) pairNextState.first).intValue();
            animationState.direction = ((Boolean) pairNextState.second).booleanValue();
            animationState.counter = 0;
        } else {
            unit.setAssetsState(animationState.assetsState);
            animationState.counter++;
        }
        this.mAnimationStates.put(name, animationState);
    }
}
